\node[anchor=west] (toplabel) at (1,{sqrt(7)+1.2}) {\special{dvisvgm:raw <g data-graph-text="tick">}$\sqrt7$\special{dvisvgm:raw </g>}};
\node[anchor=west] (bottomlabel) at (1,{-sqrt(7)-1.2}) {\special{dvisvgm:raw <g data-graph-text="tick">}$-\sqrt7$\special{dvisvgm:raw </g>}};
